// Get the output from the previous node, which contains both the resume and cover letter
// The input format is an array of items, so we get the first item
const llmOutput = items[0].json.text;

// Check if the output is valid before processing
if (!llmOutput) {
  // Return an empty object or handle the error gracefully
  return [{}];
}

// Regex to find and remove the markdown code block delimiters and headings.
// It looks for "### REWRITTEN RESUME ###", "### COVER LETTER ###", and the markdown code fences like ```html and ```.
const regex = /###\s(REWRITTEN RESUME|COVER LETTER)\s###\n?```html\n|```/g;
const cleanedOutput = llmOutput.replace(regex, '').trim();

// Split the content into the two distinct parts based on the cleaned heading
const parts = cleanedOutput.split('### COVER LETTER ###');

// The resume is the first part, and the cover letter is the second
const cleanedResume = parts[0].trim();
const cleanedCoverLetter = parts[1] ? parts[1].trim() : '';

// Return a new object with the cleaned resume and cover letter
// These new fields can now be referenced in the Gmail node.
return [{
  json: {
    cleanedCoverLetter: cleanedCoverLetter,
    cleanedResume: cleanedResume
  }
}];

